mapper.select:
SELECT id, device_no, msg_id, report_time,
       CAST(metrics_json AS CHAR) AS metrics_json
FROM device_report
WHERE device_no = #{deviceNo}
  AND report_time >= #{start}
  AND report_time <= #{end}
ORDER BY report_time DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM device_report
WHERE device_no = #{deviceNo}
  AND report_time >= #{start}
  AND report_time <= #{end}

SELECT DATE_FORMAT(report_time, '%Y-%m-%d %H:00') AS bucket,
       COUNT(*)                                    AS `count`
FROM device_report
WHERE device_no = #{deviceNo}
  AND report_time >= #{start}
  AND report_time <= #{end}
GROUP BY DATE_FORMAT(report_time, '%Y-%m-%d %H:00')
ORDER BY bucket

SELECT DATE_FORMAT(report_time, '%Y-%m-%d') AS bucket,
       COUNT(*)                             AS `count`
FROM device_report
WHERE device_no = #{deviceNo}
  AND report_time >= #{start}
  AND report_time <= #{end}
GROUP BY DATE_FORMAT(report_time, '%Y-%m-%d')
ORDER BY bucket
